  String? _chainKeyNameFor(String provider, String baseUrl) {
    final resolver = config.modelRolesResolver;
    if (resolver == null) return null;
    final refs =
        resolver.config.chainFor(
          defaultModelRole,
          cwd: config.env.cwd,
          homeDir: config.homeDir,
        ) ??
