  void _writeBandGap(
    StringBuffer row,
    int pad,
    Style fill, {
    required bool transparent,
  }) {
    if (pad <= 0) return;
    final c = FaThemeController.instance;
    if (transparent) {
      // Reset first so the gap is plain terminal background.
      if (c.profile != null) row.write('\x1b[0m');
      row.write(' ' * pad);
    } else {
      row
        ..write(c.sgrPrefix(fill))
        ..write(' ' * pad);
    }
  }

