    for (final ref in refs) {
      final refBase = ref.baseUrl;
      if (ref.provider == provider &&
          refBase != null &&
          _sameEndpoint(refBase, baseUrl)) {
        return ref.apiKeyName;
      }
    }
    return null;
  }

