    for (final entry in entries) {
      if (!_sameEndpoint(entry.baseUrl, model.baseUrl)) continue;
      if (pinnedKey != null && entry.keyName == pinnedKey) {
        return entry.name;
      }
      first ??= entry.name;
    }
    return first;
  }

