{"command":"cat > test/cli/probe_smoke_test.dart << 'EOF'
import 'dart:io';
import 'package:flutter_agent_harness/src/cli/status_line_git_probe.dart';
import 'package:test/test.dart';

void main() {
  test('SMOKE default runner: real repo, non-repo, deleted cwd', () async {
    Future<void> pump() => Future<void>.delayed(Duration.zero);
    final repo = Directory.current.path;
    final probe = StatusLineGitProbe(); // REAL git runner + REAL clock
    // Real repo: branch resolves.
    probe.current(repo);
    await pump();
    final v = probe.current(repo);
    expect(v, isNotNull);
    // ignore: avoid_print
    print('repo branch=${v!.branch} staged=${v.staged} unstaged=${v.unstaged} untracked=${v.untracked}');
    expect(v.branch, isNotEmpty);
    // Deleted cwd: Process.start throws -> null, no crash.
    final gone = Directory.systemTemp.path + '/does-not-exist-923';
    probe.current(gone);
    await pump();
    expect(probe.current(gone), isNull, reason: 'deleted cwd is a failure -> hidden');
    // Non-repo: null and STAYS null after ttl (fix under test).
    // ttl is 5s; wait 5.2s and re-poll to prove the negative clears/stays clear.
    final tmp = await Directory.systemTemp.createTemp('probe923');
    try {
      probe.current(tmp.path);
      await pump();
      expect(probe.current(tmp.path), isNull, reason: 'non-repo -> hidden');
      await Future<void>.delayed(const Duration(seconds: 5, milliseconds: 300));
      expect(probe.current(tmp.path), isNull, reason: 'still hidden after ttl re-poll');
    } finally {
      await tmp.delete(recursive: true);
    }
  }, timeout: const Timeout(Duration(seconds: 30)));
}
EOF
